void Solver::bump_var(int var, double coeff) {
    // Increment activity with the current increment factor scaled by coeff
    activity[var] += var_inc * coeff;

    // If any activity becomes too large, rescale all activities and the increment factor.
    // This prevents floating‑point overflow and keeps the relative ordering stable.
    const double RESCALE_THRESHOLD = 1e80;
    if (activity[var] > RESCALE_THRESHOLD) {
        double scale = 1e-80;                     // bring values back to a safe range
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent: if the variable is already in the heap,
    // update its position according to the new activity.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
